 async void Import(string[] paths){if(busy)return;busy=true;Info("Importing media…");Checkpoint();foreach(var path in paths){try{var m=await Task.Run(()=>Engine.Probe(path));await CreateThumbnail(m);project.Media.Add(m);}catch(Exception e){MessageBox.Show(path+"\n"+e.Message,"Import failed");}}busy=false;Refresh();Info("Imported "+project.Media.Count+" media items");}
 void Relink(){var item=bin==null?null:bin.SelectedItem as ListBoxItem;if(item==null)return;var old=(Media)item.Tag;var d=new OpenFileDialog{Title="Locate replacement for "+old.Name,Filter="All media|*.*"};if(d.ShowDialog()!=true)return;try{var m=Engine.Probe(d.FileName);if(project.Clips.Any(c=>c.MediaId==old.Id&&m.Kind!="image"&&c.In+c.Duration*c.Speed>m.Duration+.05))throw new Exception("Replacement is too short for existing clips.");Checkpoint();old.Path=m.Path;old.Name=m.Name;old.Kind=m.Kind;old.Duration=m.Duration;old.HasAudio=m.HasAudio;old.Width=m.Width;old.Height=m.Height;Refresh();}catch(Exception e){MessageBox.Show(e.Message,"Relink failed");}}
 void Add(Media m,double start,int track){if(busy)return;if(project.LockedTracks.Contains(track)){Info("Unlock the target track before inserting media.");return;}Checkpoint();selected=new Clip{Id=Guid.NewGuid().ToString(),MediaId=m.Id,Start=start,Duration=m.Kind=="image"?5:m.Duration,Track=track,Volume=1,Opacity=1,Scale=1,NativeSize=true};if(!projectConfigured&&project.Clips.Count==0&&m.Kind!="audio"&&m.Width>=160&&m.Height>=120){project.Width=Math.Min(3840,m.Width/2*2);project.Height=Math.Min(2160,m.Height/2*2);projectConfigured=true;}project.Clips.Add(selected);Refresh();}

 async Task CreateThumbnail(Media m){
  try{if(thumbnails.ContainsKey(m.Id)||!File.Exists(m.Path))return;string p=m.Path;if(m.Kind!="image"){p=Path.Combine(Path.GetTempPath(),"TasiaCraft-card-"+m.Id+".png");if(!File.Exists(p)){string filter=m.Kind=="audio"?" -filter_complex aformat=channel_layouts=mono,showwavespic=s=640x80:colors=0x5bd6a2 ":" -vf scale=320:-1 ";await Task.Run(()=>Engine.Run("ffmpeg","-y -i "+Engine.Quote(m.Path)+filter+" -frames:v 1 "+Engine.Quote(p)));}}var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.UriSource=new Uri(p);image.EndInit();image.Freeze();thumbnails[m.Id]=image;if(bin!=null&&activePanel=="Media")Panel("Media");DrawTimeline();}catch(Exception e){Info("Thumbnail unavailable: "+e.Message);}
