 void ImportCaptions(){var d=new OpenFileDialog{Filter="SubRip captions|*.srt"};if(d.ShowDialog()!=true)return;try{var blocks=System.Text.RegularExpressions.Regex.Split(File.ReadAllText(d.FileName).Trim(),@"\r?\n\s*\r?\n");Checkpoint();foreach(var block in blocks){var lines=block.Split(new[]{"\r\n","\n"},StringSplitOptions.None);int i=Array.FindIndex(lines,x=>x.Contains("-->"));if(i<0)continue;var times=lines[i].Split(new[]{"-->"},StringSplitOptions.None);double a=TimeSpan.Parse(times[0].Trim().Replace(',','.')).TotalSeconds,b=TimeSpan.Parse(times[1].Trim().Replace(',','.')).TotalSeconds;if(b<=a)continue;project.Clips.Add(new Clip{Id=Guid.NewGuid().ToString(),Text=string.Join("\n",lines.Skip(i+1)),Start=a,Duration=b-a,Track=project.TrackCount-1,Opacity=1,Scale=1,Volume=1,Y=project.Height*.3});}Refresh();}catch(Exception e){MessageBox.Show(e.Message,"Captions");}}
 void Split(){if(SelectedClips().Count>1){Info("Open the group and select one member to split.");return;}if(TrackLocked(selected)){Info("Track is locked.");return;}if(selected==null||head<=selected.Start+.01||head>=selected.Start+selected.Duration-.01)return;Checkpoint();var c=selected;var b=json.Deserialize<Clip>(json.Serialize(c));double offset=head-c.Start;b.Id=Guid.NewGuid().ToString();b.Start=head;b.In+=offset*c.Speed;b.Duration-=offset;c.Duration=offset;c.FadeOut=0;b.FadeIn=0;c.FadeIn=Math.Min(c.FadeIn,c.Duration);b.FadeOut=Math.Min(b.FadeOut,b.Duration);project.Clips.Add(b);var group=ClipGroups.ForClip(project,c);if(group!=null)group.ClipIds.Add(b.Id);selected=b;Refresh();}
