 void Settings(){var w=new Window{Title="Project settings",Owner=this,Width=330,Height=320,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=panel,Foreground=Brushes.White};var s=new StackPanel{Margin=new Thickness(16)};w.Content=s;var boxes=new List<TextBox>();foreach(var pair in new[]{"Width|"+project.Width,"Height|"+project.Height,"Frame rate|"+project.Fps}){var p=pair.Split('|');s.Children.Add(Text(p[0]));var b=new TextBox{Text=p[1],Margin=new Thickness(8)};boxes.Add(b);s.Children.Add(b);}s.Children.Add(Btn("Apply",()=>{int a,b,c;if(!int.TryParse(boxes[0].Text,out a)||!int.TryParse(boxes[1].Text,out b)||!int.TryParse(boxes[2].Text,out c)||a<160||a>3840||b<120||b>2160||c<1||c>60||a%2!=0||b%2!=0){MessageBox.Show("Use even dimensions 160–3840 × 120–2160 and 1–60 fps.");return;}Checkpoint();project.Width=a;project.Height=b;project.Fps=c;projectConfigured=true;w.Close();Refresh();},true));w.ShowDialog();}
