eNoWindow=true,RedirectStandardInput=true,RedirectStandardError=true};recorder=new Process{StartInfo=psi};recorder.ErrorDataReceived+=(o,e)=>{if(e.Data!=null)try{File.AppendAllText(log,e.Data+Environment.NewLine);}catch{}};recorder.Start();recorder.BeginErrorReadLine();record.Content="■ Stop recording";Info("Recording to "+recordedPath);w.Close();}catch(Exception e){recorder=null;MessageBox.Show(e.Message,"Capture failed");}},true));w.ShowDialog();}
 string DeviceList(){var p=new Process{StartInfo=new ProcessStartInfo(Engine.Tool("ffmpeg"),"-list_devices true -f dshow -i dummy"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true}};p.Start();string r=p.StandardError.ReadToEnd();p.WaitForExit();return r;}
 void Keys(object s,KeyEventArgs e){if(e.OriginalSource is TextBox && !((Keyboard.Modifiers&ModifierKeys.Control)!=0&&(e.Key==Key.S||e.Key==Key.O||e.Key==Key.I||e.Key==Key.N||e.Key==Key.R||e.Key==Key.H)))return;if((Keyboard.Modifiers&ModifierKeys.Control)!=0){if(e.Key==Key.A)SelectAllClips();else if(e.Key==Key.G)GroupSelection();else if(e.Key==Key.U)UngroupSelection();else if(e.Key==Key.OemSemicolon)ToggleCanvasSnapping();else if(e.Key==Key.S)Save((Keyboard.Modifiers&ModifierKeys.Shift)!=0);else if(e.Key==Key.O)Open();else if(e.Key==Key.I)ImportDialog();else if(e.Key==Key.N)New();else if(e.Key==Key.R)Record();else if(e.Key==Key.H)ShowHome();else if(e.Key==Key.Z)Undo();else if(e.Key==Key.Y)Redo();else if(e.Key==Key.D)Duplicate();else if(e.Key==Key.C)Copy();else if(e.Key==Key.X)Cut();else if(e.Key==Key.V)Paste();else return;}else{if(e.Key==Key.Space)TogglePlay();else if(e.Key==Key.S)Split();else if(e.Key==Key.F9)Record();else if(e.Key==Key.F10){if(recorder!=null)Record();}else if(e.Key==Key.Delete)Delete();else if(e.Key==Key.Right)Seek(head+1.0/project.Fps);else if(e.Key==Key.Left)Seek(head-1.0/project.Fps);else return;}e.Handled=true;}
